from itertools import combinations
A = list(range(6))
B = list(range(6, 13))
edges = [(a,b) for a in A for b in B]
E = set(edges)

# Check triangle-free
for u,v,w in combinations(range(13), 3):
    if (min(u,v),max(u,v)) in E and (min(v,w),max(v,w)) in E and (min(u,w),max(u,w)) in E:
        print("Triangle!", u,v,w); break
else:
    print("Triangle-free OK")

# Check maximal
adj = {i:set() for i in range(13)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

for u,v in combinations(range(13),2):
    if (u,v) not in E:
        if not (adj[u] & adj[v]):
            print("Not maximal:", u,v); break
else:
    print("Maximal OK")

print(len(edges), "edges")
print(edges)
